import {FIRE_MODES} from './weapons.js';
import * as THREE from 'three';
import {World} from './world.js';
import {Simulation,dist,clamp} from './simulation.js';
import {OBJECTIVES,WORLD,BUILDINGS,ROUTES,SUPPLIES,DIFFICULTIES} from './mission.js';
import {GameAudio} from './audio.js';
const $=s=>document.querySelector(s),touch=matchMedia('(pointer:coarse)').matches;
let lang='bn',mode='loading',world,sim,zoom=1,tactical=false,toastTime=0,endTime=0,mouseAim=false,mouseFire=false,pendingFire=false,lastStep=0,uiClock=0,combatWatch=0,combatMaxFrame=0;
const keys=new Set(),moveStick={x:0,z:0},aimStick={x:0,z:0},mouse={x:innerWidth/2,y:innerHeight/2};
const audio=new GameAudio(),tr=(bn,en)=>lang==='bn'?bn:en;
const fmtTime=t=>`${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;
const bnNumber=n=>lang==='bn'?String(n).replace(/[0-9]/g,d=>'০১২৩৪৫৬৭৮৯'[Number(d)]):String(n);
if(touch)$('#quality').value='mobile';
function toast(bn,en){$('#toast-text').textContent=tr(bn,en||bn);$('#toast').classList.add('show');toastTime=5.5;}
function clearInput(){keys.clear();moveStick.x=moveStick.z=aimStick.x=aimStick.z=0;mouseFire=false;pendingFire=false;document.querySelectorAll('.stick i').forEach(n=>n.style.transform='translate(0,0)');}
function objectiveUI(){if(sim.training){$('#phase-label').textContent=tr('অনুশীলন মাঠ','TRAINING RANGE');$('#objective-title').textContent=tr('অস্ত্র ও কৌশল অনুশীলন','Combat drills');$('#objective-desc').textContent=tr('T: অস্ত্র বদল · B: ফায়ার মোড · F: কাছ থেকে আঘাত। পেছন থেকে নিঃশব্দে এগিয়ে যান।','T: switch weapon · B: fire mode · F: melee. Approach from behind for a quiet takedown.');$('.progress-track').innerHTML='';return;}const o=OBJECTIVES[sim.phase];$('#phase-label').textContent=`${tr('অপারেশন ময়ূখ','OPERATION MOYUKH')} / ${bnNumber(String(sim.phase+1).padStart(2,'0'))}—${bnNumber('08')}`;$('#objective-title').textContent=tr(o.bn,o.en);$('#objective-desc').textContent=tr(o.desc,o.edesc);$('.progress-track').innerHTML=OBJECTIVES.map((_,i)=>`<i class="${i<=sim.phase?'done':''}"></i>`).join('');$('#captive-status').classList.toggle('hidden',!sim.captured);}
function start(){sim.difficulty=$('#difficulty').value;sim.reset();combatMaxFrame=0;combatWatch=0;world.setQuality($('#quality').value);mode='playing';$('#menu').classList.add('hidden');$('#dialog').classList.add('hidden');$('#tactical-map').classList.add('hidden');$('#cinematic').classList.add('hidden');$('#hud').classList.remove('hidden');$('#pause').classList.remove('hidden');$('#map-button').classList.remove('hidden');document.body.classList.add('playing');clearInput();audio.start();objectiveUI();for(const [id,a] of world.actors)if(id.startsWith('crowd')){world.scene.remove(a.root);world.actors.delete(id);}world.camera.position.set(sim.player.x,29,sim.player.z+24);}
function menu(){mode='menu';clearInput();$('#menu').classList.remove('hidden');$('#hud').classList.add('hidden');$('#dialog').classList.add('hidden');$('#tactical-map').classList.add('hidden');$('#cinematic').classList.add('hidden');$('#crosshair').classList.add('hidden');$('#pause').classList.add('hidden');$('#map-button').classList.add('hidden');document.body.classList.remove('playing');$('#damage').style.opacity=0;sim.reset();for(const [id,a] of world.actors)if(id.startsWith('crowd')){world.scene.remove(a.root);world.actors.delete(id);}}
function dialog(title,body,primary,onPrimary,secondary,onSecondary){clearInput();$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog-primary').textContent=primary;$('#dialog-primary').onclick=onPrimary;$('#dialog-secondary').textContent=secondary||'';$('#dialog-secondary').classList.toggle('hidden',!secondary);$('#dialog-secondary').onclick=onSecondary||null;$('#dialog').classList.remove('hidden');}
function pause(){if(mode==='playing'){mode='paused';dialog(tr('অভিযান স্থগিত','Operation paused'),`<p>${tr('অবস্থান সংরক্ষিত আছে। পরিস্থিতি পর্যালোচনা করে আবার এগিয়ে যান।','Your position is held. Review the situation before moving on.')}</p><div class="menu-settings"><label><span>${tr('দৃশ্যের মান','Graphics quality')}</span><select id="pause-quality"><option value="mobile">Performance</option><option value="balanced">High</option><option value="ultra">Ultra</option></select></label></div>`,tr('অভিযানে ফিরুন ↗','Resume operation ↗'),()=>{world.setQuality($('#pause-quality').value);$('#quality').value=$('#pause-quality').value;mode='playing';$('#dialog').classList.add('hidden');},tr('মূল মেনু','Main menu'),menu);$('#pause-quality').value=world.quality;}else if(mode==='paused')$('#dialog-primary').click();else if(mode==='map')toggleMap();}
function toggleMap(){if(mode==='map'){mode='playing';$('#tactical-map').classList.add('hidden');return;}if(mode!=='playing')return;mode='map';clearInput();$('#tactical-map').classList.remove('hidden');$('#mission-list').innerHTML=OBJECTIVES.map((o,i)=>`<div class="${i===sim.phase?'active':''}"><strong>${i<sim.phase?'✓':String(i+1).padStart(2,'0')} · ${tr(o.bn,o.en)}</strong><small>${tr(o.desc,o.edesc)}</small></div>`).join('')+`<p class="map-key">${tr('● আপনি · ● বাচ্চু · ◈ লক্ষ্য · + রসদ<br>লাল: কাছের শত্রু · বাদামি: ভবন<br>মানচিত্র খোলা থাকলে অভিযান স্থগিত থাকে।','● You · ● Bachchu · ◈ Objective · + Supplies<br>Red: nearby enemies · Brown: buildings<br>Opening this map pauses the operation.')}</p>`;drawMap($('#large-map'),true);}
function manual(){dialog(tr('ফিল্ড ম্যানুয়াল','Field manual'),`<p>${tr('ভিক্টর সেবল একজন সম্পূর্ণ কাল্পনিক চোরাচালান-চক্রের নেতা। তার সঙ্গে কোনো বাস্তব ব্যক্তির সম্পর্ক নেই। আটটি ধাপ শেষ করে তাকে আটক করুন এবং ঘাটে নিয়ে ফিরুন।','Viktor Sable is a wholly fictional smuggling kingpin, unrelated to any real person. Complete eight objectives, capture him and escort him to the extraction dock.')}</p><div class="manual">${[['WASD','চলাফেরা','Move'],['C','নিচু হয়ে চলুন','Crouch'],['SHIFT','দৌড়ান','Sprint'],['E','ধরে রাখুন: কাজ','Hold: interact'],['CLICK','গুলি / খালি হাতে আঘাত','Fire / unarmed strike'],['F','কাছ থেকে আঘাত / পেছন থেকে কাবু','Melee / rear takedown'],['T','সংগৃহীত অস্ত্র বদল','Cycle collected weapons'],['B','একক / বার্স্ট / স্বয়ংক্রিয়','Change fire mode'],['R','রিলোড','Reload'],['Q','সঙ্গী: চলুন / থাকুন','Companion: follow / hold'],['G','শব্দ দিয়ে বিভ্রান্তি','Noise decoy'],['X','ধোঁয়ার আড়াল','Smoke grenade'],['H','প্রাথমিক চিকিৎসা','Medkit'],['M','পরিকল্পনার মানচিত্র','Tactical map'],['V / SCROLL','ক্যামেরা / জুম','Camera / zoom']].map(([k,b,e])=>`<div><kbd>${k}</kbd>${tr(b,e)}</div>`).join('')}</div><p>${tr('মোবাইলে বাম স্টিক দিয়ে চলুন, ডান স্টিক টেনে তাক ও গুলি করুন। কাজের বোতাম ধরে রাখুন। ঝোপে বসে থাকলে দৃশ্যমানতা কমে; দৌড় ও গুলির শব্দ পাহারাদারকে আকৃষ্ট করে। ধোঁয়া দৃষ্টি আটকায়। শত্রু শেষ দেখা অবস্থান মনে রাখে এবং রেডিওতে খবর দেয়।','On mobile, use the left stick to move and drag the right stick to aim and fire. Hold ACT for interactions. Crouching in brush lowers visibility. Running and gunfire attract guards. Smoke blocks sight. Enemies remember your last position and call for help.')}</p><p>${tr('রেডিও রিলে বন্ধ করলে অতিরিক্ত শত্রু আসা বন্ধ হয়। বিদ্যুৎ বন্ধ করলে ক্যামেরা ও সার্চলাইট নিভে যায়। গুলি, চিকিৎসা ও ধোঁয়া সীমিত—রসদের বাক্স খুঁজুন।','Disabling the relay prevents reinforcements. Cutting power disables cameras and searchlights. Ammunition, medkits and smoke are limited. Search for supply caches.')}</p><p>${tr('সর্বোচ্চ মানে ambient occlusion ও bloom চালু থাকে। ধীরগতির ফোনে Performance বেছে নিন।','Ultra adds ambient occlusion and bloom. Choose Performance on slower phones.')}</p>`,tr('বুঝেছি ↗','Understood ↗'),()=>$('#dialog').classList.add('hidden'));}
function result(win){mode=win?'won':'lost';$('#cinematic').classList.add('hidden');$('#crosshair').classList.add('hidden');let best=null;try{const key='neighbour-v2-best-'+sim.difficulty;best=Number(localStorage.getItem(key)||0);if(win&&(!best||sim.time<best)){best=sim.time;localStorage.setItem(key,String(best));}}catch{}const accuracy=sim.shots?Math.round(sim.hits/sim.shots*100):100;dialog(win?tr('অভিযান সম্পন্ন','Operation complete'):tr('অভিযান ব্যর্থ','Operation failed'),`<p>${win?tr('ভিক্টর সেবলকে নিয়ে ফিরে এসেছেন। ক্ষুব্ধ জনতা তাকে ঘিরে ধরে; সংক্ষিপ্ত, অরক্তাক্ত ধস্তাধস্তির পর দৃশ্য শেষ হয়। বাচ্চুর কথা: “অভিযান শেষ। এবার অন্তত চা-টা শান্তিতে খাই।”','Viktor Sable is back across the frontier. An angry crowd surrounds him; a brief, non-graphic scuffle closes the scene. Bachchu: “Operation complete. Now let us at least have our tea in peace.”'):tr('প্রতিরোধ ভেঙে বেরোতে পারেননি। ধোঁয়া ব্যবহার করুন, অবস্থান বদলান এবং রেডিও রিলে যত দ্রুত সম্ভব বন্ধ করুন।','You could not break through. Use smoke, change position and disable the radio relay early.')}</p><div class="score-grid"><div><strong>${fmtTime(sim.time)}</strong><small>${tr('সময়','TIME')}</small></div><div><strong>${sim.completed.length}/8</strong><small>${tr('লক্ষ্য','OBJECTIVES')}</small></div><div><strong>${accuracy}%</strong><small>${tr('নির্ভুলতা','ACCURACY')}</small></div></div><p>${tr('কাবু করা শত্রু','Enemies neutralized')}: ${bnNumber(sim.knockouts)} · ${tr('সতর্কসংকেত','Alerts')}: ${bnNumber(sim.stats.alerts)}${best&&win?' · Best '+fmtTime(best):''}</p>`,tr('আবার অভিযান ↗','Retry operation ↗'),start,tr('মূল মেনু','Main menu'),menu);}
function processEvents(){for(const e of sim.events){if(e.type==='shot'){combatWatch=.6;if(e.hit){$('#crosshair').classList.add('hit');setTimeout(()=>$('#crosshair').classList.remove('hit'),160);}}world.effect(e);audio.event(e,sim.player);if(e.type==='dialogue'&&e.text)toast(...e.text);if(e.type==='message')toast(e.bn,e.en);if(e.type==='objective')objectiveUI();if(e.type==='reinforcement')toast('রেডিওতে খবর পৌঁছেছে। অতিরিক্ত শত্রু আসছে।','The radio call got through. Reinforcements are arriving.');if(e.type==='pickup')toast('রসদ সংগ্রহ করা হয়েছে। সরঞ্জাম পরীক্ষা করুন।','Supplies collected. Check your equipment.');if(e.type==='lose')result(false);if(e.type==='win'){mode='cinematic';endTime=0;clearInput();$('#cinematic').classList.remove('hidden');$('#hud').classList.add('hidden');}}sim.events.length=0;}
function hud(){const p=sim.player;$("#world").dataset.diagnostics=JSON.stringify({x:p.x,z:p.z,phase:sim.phase,health:p.health,quality:world.quality,shots:sim.shots,programs:world.renderer.info.programs.length,combatMaxFrame:Math.round(combatMaxFrame)});$('#health-text').textContent=bnNumber(Math.ceil(p.health));$('#health-bar').style.width=p.health+'%';$('#stamina-bar').style.width=p.stamina+'%';$('#damage').style.opacity=p.hit>0?.55:p.health<30?.18:0;const awareness=Math.max(sim.cameraAlarm,...sim.guards.filter(g=>g.state!=='down').map(g=>g.awareness),0);$('#detection-bar').style.width=awareness*100+'%';$('#detection-label').textContent=awareness>.95?tr('অবস্থান প্রকাশিত','POSITION EXPOSED'):awareness>.2?tr('সন্দেহভাজন','SUSPICIOUS'):tr('নজরের বাইরে','UNDETECTED');$('#eye').style.color=awareness>.8?'#f4936b':'#cbd5a4';$('#alarm-bar').style.width=sim.alarm+'%';$('#alarm-value').textContent=Math.floor(sim.alarm)+'%';$('#stance').textContent=p.heal?tr('চিকিৎসা চলছে…','APPLYING MEDKIT…'):sim.inSmoke(p)?tr('ধোঁয়ার আড়ালে','IN SMOKE'):sim.hidden()?tr('ঘন ঝোপের আড়ালে','CONCEALED IN BRUSH'):p.crouch?tr('নিচু হয়ে চলছেন','CROUCHED'):tr('স্বাভাবিক চলন','STANDING');$('#weapon').textContent=p.weapon?tr(sim.weaponSpec().bn,sim.weaponSpec().en):tr('খালি হাত','UNARMED');$('#fire-mode-label').textContent=p.weapon?tr(...FIRE_MODES[p.fireMode]):tr('নীরবে কাছে যান','APPROACH QUIETLY');$('#ammo').textContent=p.weapon?bnNumber(p.mag):'—';$('#reserve').textContent=p.reload?tr('রিলোড…','RELOADING…'):p.weapon?'/ '+bnNumber(p.reserve):tr('F · কাবু করুন','F · TAKEDOWN');$('#buddy-state').textContent=sim.buddy.follow?tr('অনুসরণ করছে · সহায়তায় প্রস্তুত','Following · ready to assist'):tr('নির্ধারিত অবস্থানে আছে','Holding position');$('#meds').textContent=`H ✚ ${sim.medkits}`;$('#smokes').textContent=`X ◌ ${sim.smokeCount}`;$('#decoys').textContent=`G ◇ ${sim.decoys}`;document.querySelector('[data-action="heal"] small').textContent='HEAL '+sim.medkits;document.querySelector('[data-action="smoke"] small').textContent='SMOKE '+sim.smokeCount;document.querySelector('[data-action="decoy"] small').textContent='DECOY '+sim.decoys;$('#zone').textContent=p.z>0?tr('বাংলাদেশ · কাল্পনিক সীমান্ত','BANGLADESH · FICTIONAL'):tr('ভারত · কাল্পনিক সেক্টর','INDIA · FICTIONAL');$('#clock').textContent=fmtTime(sim.time);$('#captive-distance').textContent=tr('বন্দি · দূরত্ব ','CAPTIVE · ')+bnNumber(Math.round(dist(p,sim.captive)))+' m';const n=sim.interactable();$('#interact').classList.toggle('hidden',!n);if(n){$('#interact strong').textContent=tr(n.bn,n.en);$('#interact kbd').textContent=n.type==='blocked'?'!':n.target?.id==='extract'?'◷':'E';$('#interact i').style.width=clamp(sim.upload/(n.duration||1)*100,0,100)+'%';}$('#target-marker').classList.toggle('hidden',sim.training);const o=OBJECTIVES[sim.phase],v=new THREE.Vector3(o.x,3,o.z).project(world.camera);$('#target-marker').style.left=clamp((v.x*.5+.5)*innerWidth,28,innerWidth-28)+'px';$('#target-marker').style.top=clamp((-v.y*.5+.5)*innerHeight,104,innerHeight-190)+'px';$('#target-distance').textContent=bnNumber(Math.round(dist(p,o)))+' m';drawMap($('#minimap'));}
function drawMap(canvas,large=false){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,sx=w/(WORLD.x*2),sz=h/(WORLD.z*2),mx=x=>w/2+x*sx,mz=z=>h/2+z*sz;ctx.fillStyle='#122b2d';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#8b9f8720';ctx.lineWidth=1;for(let x=0;x<w;x+=w/12){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke();}for(let z=0;z<h;z+=h/17){ctx.beginPath();ctx.moveTo(0,z);ctx.lineTo(w,z);ctx.stroke();}ctx.fillStyle='#3e7276';ctx.fillRect(mx(-101),0,18*sx,h);ctx.fillStyle='#7a897537';ctx.fillRect(mx(-3),0,6*sx,h);for(const z of [101,42,-35,-103])ctx.fillRect(0,mz(z-2),w,4*sz);ctx.strokeStyle='#c5bc85';ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();ctx.setLineDash([]);for(const x of ROUTES){ctx.fillStyle='#b4c092';ctx.fillRect(mx(x)-3,h/2-2,6,4);}for(const b of BUILDINGS){ctx.fillStyle='#64776b';ctx.fillRect(mx(b.x-b.w/2),mz(b.z-b.d/2),b.w*sx,b.d*sz);}const dot=(p,r,c)=>{ctx.beginPath();ctx.arc(mx(p.x),mz(p.z),r,0,Math.PI*2);ctx.fillStyle=c;ctx.fill();};for(const g of sim.guards)if(g.state!=='down'&&(dist(g,sim.player)<38||sim.difficulty==='story')){dot(g,large?4:2,g.state==='combat'?'#ff8164':'#bf987d');if(large){ctx.strokeStyle='#ba967355';ctx.beginPath();ctx.moveTo(mx(g.x),mz(g.z));ctx.arc(mx(g.x),mz(g.z),24*sx,Math.PI/2-g.angle-.6,Math.PI/2-g.angle+.6);ctx.closePath();ctx.stroke();}}for(const s of SUPPLIES)if(!sim.supplyTaken.has(s.id)){ctx.fillStyle='#91bdab';ctx.font=`${large?15:8}px sans-serif`;ctx.textAlign='center';ctx.fillText('+',mx(s.x),mz(s.z));}for(let i=0;i<OBJECTIVES.length;i++){const o=OBJECTIVES[i];if(!large&&i!==sim.phase)continue;ctx.strokeStyle=i<sim.phase?'#719487':i===sim.phase?'#e6c683':'#748982';ctx.lineWidth=i===sim.phase?2:1;ctx.strokeRect(mx(o.x)-4,mz(o.z)-4,8,8);if(large){ctx.fillStyle=ctx.strokeStyle;ctx.font='12px sans-serif';ctx.fillText(String(i+1),mx(o.x)+10,mz(o.z)+4);}}dot(sim.buddy,large?5:2.7,'#84c8c3');if(sim.captured)dot(sim.captive,large?5:3,'#c3a4c1');dot(sim.player,large?6:3.6,'#e7dfb4');ctx.strokeStyle='#e7dfb4';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(mx(sim.player.x),mz(sim.player.z));ctx.lineTo(mx(sim.player.x+Math.sin(sim.player.angle)*6),mz(sim.player.z+Math.cos(sim.player.angle)*6));ctx.stroke();}
$('#start').onclick=()=>{if(world?.loaded)start();};$('#help').onclick=manual;$('#practice').onclick=()=>{start();sim.training=true;sim.events=[];sim.radio=false;sim.power=false;Object.assign(sim.player,{x:0,z:130,angle:Math.PI});sim.buddy.x=3;sim.buddy.z=132;sim.guards=[sim.makeGuard(0,122,0),sim.makeGuard(10,110,1)];sim.guards.forEach(g=>{g.angle=Math.PI;g.patrol=g.patrol.map(()=>({x:g.x,z:g.z}));});for(const id of ['rifle','carbine','marksman'])sim.acquireWeapon(id,60);sim.phase=0;zoom=.65;objectiveUI();toast('অনুশীলন: গুলি চালান, অস্ত্র বদলান অথবা পেছন থেকে কাবু করুন।','Practice firing, switching weapons and rear takedowns.');};$('#pause').onclick=pause;$('#map-button').onclick=toggleMap;$('#close-map').onclick=toggleMap;$('.brand').onclick=e=>{e.preventDefault();if(mode==='playing')pause();};$('#sound').onclick=()=>{audio.start();audio.setMuted(!audio.muted);$('#sound').textContent=audio.muted?'♩':'♪';};$('#quality').onchange=()=>world?.setQuality($('#quality').value);
$('#language').onclick=()=>{lang=lang==='bn'?'en':'bn';document.documentElement.lang=lang;$('#language').textContent=lang==='bn'?'EN':'বাংলা';$('.tagline').textContent=tr('সীমান্ত পেরিয়ে। ছায়ার আড়ালে।','Across the frontier. Under the radar.');$('.description').textContent=tr('একটি ভুল পদক্ষেপ। অসংখ্য অনিশ্চয়তা। সঙ্গী বাচ্চুকে নিয়ে শত্রুর ঘাঁটিতে অনুপ্রবেশ করুন, চোরাচালান-চক্রের নেতা ভিক্টর সেবলকে আটক করুন এবং তাকে নিয়ে ফিরে আসুন.','One wrong step. A hundred unknowns. Infiltrate the frontier with Bachchu, capture fictional smuggling kingpin Viktor Sable, and bring him back.');$('#start').innerHTML=tr('অভিযান শুরু <span>↗</span>','Deploy operation <span>↗</span>');$('#practice').textContent=tr('অনুশীলন মাঠ','Training range');$('#help').textContent=tr('ফিল্ড ম্যানুয়াল','Field manual');$('#health-label').textContent=tr('স্বাস্থ্য','HEALTH');$('#weapon-label').textContent=tr('সরঞ্জাম','EQUIPMENT');if(sim)objectiveUI();};
addEventListener('keydown',e=>{if(e.code==='Escape'){pause();return;}if(e.code==='KeyM'){e.preventDefault();toggleMap();return;}if(mode!=='playing')return;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;const cmds={KeyC:'crouch',KeyR:'reload',KeyQ:'buddy',KeyG:'decoy',KeyX:'smoke',KeyH:'heal',KeyT:'weapon',KeyB:'firemode',KeyF:'melee'};if(cmds[e.code])sim.command(cmds[e.code]);if(e.code==='KeyV')tactical=!tactical;});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('pointerup',()=>mouseFire=false);addEventListener('blur',()=>{clearInput();if(mode==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='playing')pause();});addEventListener('contextmenu',e=>e.preventDefault());
function stick(selector,state){const el=$(selector),knob=el.querySelector('i');let pointer=null;const update=e=>{const r=el.getBoundingClientRect(),radius=r.width*.34;let x=(e.clientX-r.left-r.width/2)/radius,z=(e.clientY-r.top-r.height/2)/radius,len=Math.hypot(x,z);if(len>1){x/=len;z/=len;}state.x=x;state.z=z;knob.style.transform=`translate(${x*radius}px,${z*radius}px)`;mouseAim=false;$('#crosshair').classList.add('hidden');};el.addEventListener('pointerdown',e=>{if(mode!=='playing')return;e.preventDefault();pointer=e.pointerId;el.setPointerCapture(pointer);update(e);});el.addEventListener('pointermove',e=>{if(e.pointerId===pointer)update(e);});for(const event of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(event,e=>{if(e.pointerId!==pointer)return;pointer=null;state.x=state.z=0;knob.style.transform='translate(0,0)';});}
stick('#move-stick',moveStick);stick('#aim-stick',aimStick);document.querySelectorAll('[data-action]').forEach(el=>{el.addEventListener('pointerdown',e=>{if(mode!=='playing')return;e.preventDefault();el.setPointerCapture(e.pointerId);const a=el.dataset.action;if(a==='interact')keys.add('KeyE');else if(a==='sprint')keys.add('ShiftLeft');else sim.command(a);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(ev,()=>{if(el.dataset.action==='interact')keys.delete('KeyE');if(el.dataset.action==='sprint')keys.delete('ShiftLeft');});});
function input(){const p=sim.player,i={x:(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)+moveStick.x,z:(keys.has('KeyS')?1:0)-(keys.has('KeyW')?1:0)+moveStick.z,sprint:keys.has('ShiftLeft')||keys.has('ShiftRight'),fire:mouseFire||pendingFire,interact:keys.has('KeyE')};if(mouseAim){const target=world.aim(mouse.x,mouse.y);i.angle=Math.atan2(target.x-p.x,target.z-p.z);}if(Math.hypot(aimStick.x,aimStick.z)>.2){i.angle=Math.atan2(aimStick.x,aimStick.z);i.fire=true;}return i;}
function epilogue(dt){endTime+=dt;const center={x:78,z:140};sim.captive.x=center.x;sim.captive.z=center.z;for(let i=0;i<8;i++){const a=i*Math.PI/4,r=Math.max(1.3,7-endTime*1.3);world.animateActor('crowd'+i,{x:center.x+Math.sin(a)*r,z:center.z+Math.cos(a)*r,angle:a+Math.PI,moving:endTime<4.5},'civilian',dt);const actor=world.actors.get('crowd'+i);if(actor)actor.weapon.visible=false;}if(endTime>3.7){const a=world.actors.get('captive');if(a){a.root.rotation.z=Math.sin(endTime*21)*.16;a.root.position.y+=Math.abs(Math.sin(endTime*11))*.12;}}world.camera.position.lerp(new THREE.Vector3(center.x+12,15,center.z+18),1-Math.exp(-dt*2));world.camera.lookAt(center.x,1,center.z);if(endTime>6.5)result(true);}
let previous=performance.now(),frames=0,frameTime=0,performanceWarned=false;
function frame(now){requestAnimationFrame(frame);const rawFrame=now-previous,dt=Math.min(rawFrame/1000,.05);previous=now;if(combatWatch>0){combatMaxFrame=Math.max(combatMaxFrame,rawFrame);combatWatch-=dt;}if(!world?.loaded)return;if(mode==='playing'){sim.step(dt,input());pendingFire=false;processEvents();uiClock+=dt;if(uiClock>.08){hud();uiClock=0;}if(sim.player.moving&&sim.time-lastStep>.4){lastStep=sim.time;audio.noise(.055,sim.player.crouch?.02:.04,350);}}world.update(sim,mode==='paused'||mode==='map'?0:dt,{menu:mode==='menu',zoom,tactical});if(mode==='cinematic')epilogue(dt);if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('#toast').classList.remove('show');}world.render();frames++;frameTime+=dt;if(frameTime>12&&mode==='playing'&&!performanceWarned){if(frames/frameTime<27&&world.quality!=='mobile'){performanceWarned=true;toast('ফ্রেমরেট কম। বিরতির মেনু থেকে Performance মান বেছে নিতে পারেন।','Low frame rate. You can select Performance in the pause menu.');}frames=0;frameTime=0;}}
try{world=new World($('#world'),{quality:$('#quality').value,onProgress:n=>{$('.load-bar i').style.width=n+'%';$('#load-text').textContent=tr('দৃশ্য ও চরিত্র প্রস্তুত হচ্ছে… ','Preparing scene and characters… ')+n+'%';}});sim=new Simulation({bushes:world.bushes});await world.load();world.renderer.domElement.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;mouse.x=e.clientX;mouse.y=e.clientY;mouseAim=true;if(mode==='playing'){$('#crosshair').classList.remove('hidden');$('#crosshair').style.left=mouse.x+'px';$('#crosshair').style.top=mouse.y+'px';}});world.renderer.domElement.addEventListener('pointerdown',e=>{if(mode==='playing'&&e.button===0&&e.pointerType!=='touch'){mouseFire=true;pendingFire=true;mouse.x=e.clientX;mouse.y=e.clientY;mouseAim=true;audio.start();}});world.renderer.domElement.addEventListener('wheel',e=>zoom=clamp(zoom+e.deltaY*.0004,.65,1.65),{passive:true});addEventListener('resize',()=>world.resize());$('#loading').classList.add('hidden');mode='menu';objectiveUI();requestAnimationFrame(frame);window.neighbourGame={snapshot:()=>({mode,phase:sim.phase,health:sim.player.health,player:{x:sim.player.x,z:sim.player.z},alarm:sim.alarm,guards:sim.guards.length,quality:world.quality,drawCalls:world.renderer.info.render.calls,triangles:world.renderer.info.render.triangles})};}catch(e){$('#load-text').textContent=tr('গেম চালু করা যায়নি। পৃষ্ঠা রিফ্রেশ করুন। ','Unable to start. Please reload. ')+e.message;console.error(e);}

